import{t as e}from"./chunks/ThreePanel.BddHBCcE.js";import{G as t,H as n,U as r,tt as i}from"./chunks/framework.DF4UzXOs.js";var a=JSON.parse(`{"title":"Ray Tracing e Renderização Baseada em Física","description":"Fundamentos de Ray Tracing, Path Tracing, aceleração BVH e aceleração por hardware (RTX / DXR / Vulkan RT).","frontmatter":{"title":"Ray Tracing e Renderização Baseada em Física","sidebar_label":"Ray Tracing","description":"Fundamentos de Ray Tracing, Path Tracing, aceleração BVH e aceleração por hardware (RTX / DXR / Vulkan RT)."},"headers":[],"relativePath":"ray-tracing.md","filePath":"ray-tracing.md","lastUpdated":0}`),o=Object.assign({name:`ray-tracing.md`},{setup(a){return(a,o)=>(i(),n(`div`,null,[o[0]||=r(`<h1 id="ray-tracing" tabindex="-1">Ray Tracing <a class="header-anchor" href="#ray-tracing" aria-label="Permalink to “Ray Tracing”">​</a></h1><blockquote><p><strong>Ray Tracing</strong> é um método de computação gráfica que gera imagens simulando o trajeto óptico real da luz: raios virtuais são disparados a partir da câmera (olho do observador), intersectam geometrias no espaço tridimensional e calculam reflexões, refrações, sombras realistas e iluminação global.</p></blockquote><p>Enquanto a <strong>rasterização</strong> tradicional (utilizada em jogos clássicos) projeta primitivas poligonais diretamente no plano 2D da tela, o Ray Tracing rastreia a física dos fótons. Historicamente restrito a filmes de animação e efeitos visuais pré-renderizados, hoje opera em <strong>tempo real</strong> graças a núcleos dedicados nas GPUs modernas (RT Cores).</p><h2 id="demonstracao-interativa" tabindex="-1">Demonstração Interativa <a class="header-anchor" href="#demonstracao-interativa" aria-label="Permalink to “Demonstração Interativa”">​</a></h2><p>O painel abaixo simula o disparo de raios primários a partir do ponto de vista do observador, o cálculo de intersecção com uma esfera reflectiva e o rebatimento dos raios secundários pelo espaço.</p>`,5),t(e,{topic:`raytracing`,title:`Intersecção e Rebatimento de Raios`,subtitle:`Raios de luz virtuais atingem a geometria e produzem reflexões físicas calculadas pela normal da superfície.`}),o[1]||=r(`<hr><h2 id="conceitos-fundamentais" tabindex="-1">Conceitos Fundamentais <a class="header-anchor" href="#conceitos-fundamentais" aria-label="Permalink to “Conceitos Fundamentais”">​</a></h2><h3 id="_1-ray-casting-vs-ray-tracing-vs-path-tracing" tabindex="-1">1. Ray Casting vs Ray Tracing vs Path Tracing <a class="header-anchor" href="#_1-ray-casting-vs-ray-tracing-vs-path-tracing" aria-label="Permalink to “1. Ray Casting vs Ray Tracing vs Path Tracing”">​</a></h3><ul><li><strong>Ray Casting (1968):</strong> Dispara um raio por pixel até atingir a primeira superfície visível. Determina visibilidade e sombreamento direto, sem calcular raios secundários de reflexão.</li><li><strong>Whitted-Style Ray Tracing (1980):</strong> Adiciona recursão. Quando um raio atinge uma superfície espelhada ou transparente, novos raios reflexivos e refrativos são disparados.</li><li><strong>Path Tracing (Kajiya, 1986):</strong> Resolve a <em>Rendering Equation</em> completa usando métodos de Monte Carlo. Dispara múltiplos raios aleatórios por pixel para calcular iluminação global suave, sangramento de cor (<em>color bleeding</em>) e penumbras naturais.</li></ul><h3 id="_2-aceleracao-espacial-bvh-bounding-volume-hierarchy" tabindex="-1">2. Aceleração Espacial (BVH - Bounding Volume Hierarchy) <a class="header-anchor" href="#_2-aceleracao-espacial-bvh-bounding-volume-hierarchy" aria-label="Permalink to “2. Aceleração Espacial (BVH - Bounding Volume Hierarchy)”">​</a></h3><p>Testar cada raio contra milhões de triângulos tornaria o processo inviável. As GPUs modernas utilizam estruturas de aceleração hierárquicas como <strong>BVH</strong>:</p><ol><li>A cena é encapsulada em caixas delimitadoras (<em>AABB - Axis-Aligned Bounding Boxes</em>).</li><li>O raio primeiro testa colisão contra as caixas maiores.</li><li>Apenas se colidir com a caixa, ele subdivide e testa os triângulos internos, reduzindo a complexidade de busca de $O(N)$ para $O(\\log N)$.</li></ol><h3 id="_3-ray-tracing-em-tempo-real-hardware-rt" tabindex="-1">3. Ray Tracing em Tempo Real (Hardware RT) <a class="header-anchor" href="#_3-ray-tracing-em-tempo-real-hardware-rt" aria-label="Permalink to “3. Ray Tracing em Tempo Real (Hardware RT)”">​</a></h3><ul><li><strong>NVIDIA RTX:</strong> RT Cores dedicados para teste rápido de BVH e intersecção raio-triângulo.</li><li><strong>DirectX Raytracing (DXR):</strong> Extensão oficial do DirectX 12 para pipelines de traçado de raios.</li><li><strong>Vulkan Ray Tracing (VK_KHR_ray_tracing):</strong> API aberta padrão da Khronos para aceleração de RT em multiplataforma.</li><li><strong>Denoising (Redução de Ruído):</strong> Como renderizar 1000 raios por pixel em tempo real a 60 FPS é pesado, os jogos disparam poucos raios (1 a 4 por pixel) e usam inteligência artificial (DLSS 3.5 Ray Reconstruction, OptiX Denoiser) para remover o ruído temporal.</li></ul><hr><h2 id="links-rapidos" tabindex="-1">Links Rápidos <a class="header-anchor" href="#links-rapidos" aria-label="Permalink to “Links Rápidos”">​</a></h2><ul><li><a href="https://raytracing.github.io/" target="_blank" rel="noreferrer">Ray Tracing in One Weekend</a> — melhor ponto de partida prático</li><li><a href="https://www.scratchapixel.com/" target="_blank" rel="noreferrer">Scratchapixel: Ray Tracing</a> — fundamentos matemáticos explicados do zero</li><li><a href="https://pbr-book.org/" target="_blank" rel="noreferrer">PBRT Book (Physically Based Rendering)</a> — o livro padrão da indústria de renderização</li><li><a href="https://developer.nvidia.com/ray-tracing-gems" target="_blank" rel="noreferrer">NVIDIA Ray Tracing Gems</a> — técnicas avançadas em tempo real</li><li><a href="https://www.embree.org/" target="_blank" rel="noreferrer">Intel Embree</a> — biblioteca líder em kernels de ray tracing de alta performance</li></ul><hr><h2 id="🚀-mega-link-dump-ray-tracing-rendering" tabindex="-1">🚀 MEGA LINK DUMP - Ray Tracing &amp; Rendering <a class="header-anchor" href="#🚀-mega-link-dump-ray-tracing-rendering" aria-label="Permalink to “🚀 MEGA LINK DUMP - Ray Tracing &amp; Rendering”">​</a></h2><h3 id="📚-livros-e-tutoriais-gratuitos" tabindex="-1">📚 Livros e Tutoriais Gratuitos <a class="header-anchor" href="#📚-livros-e-tutoriais-gratuitos" aria-label="Permalink to “📚 Livros e Tutoriais Gratuitos”">​</a></h3><ul><li><a href="https://raytracing.github.io/" target="_blank" rel="noreferrer">Ray Tracing in One Weekend</a> — / <a href="https://github.com/RayTracing/raytracing.github.io" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://raytracing.github.io/books/RayTracingInOneWeekend.html" target="_blank" rel="noreferrer">PDF</a> / <a href="https://raytracing.github.io/" target="_blank" rel="noreferrer">Online Book</a> / <a href="https://github.com/RayTracing/raytracing.github.io/releases" target="_blank" rel="noreferrer">C++ Code</a></li><li><a href="https://raytracing.github.io/books/RayTracingTheNextWeek.html" target="_blank" rel="noreferrer">Ray Tracing: The Next Week</a> — BVH, texturas, perlin noise e volumes — / <a href="https://raytracing.github.io/books/RayTracingTheNextWeek.html" target="_blank" rel="noreferrer">Livro</a> / <a href="https://github.com/RayTracing/raytracing.github.io" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://raytracing.github.io/books/RayTracingTheRestOfYourLife.html" target="_blank" rel="noreferrer">Ray Tracing: The Rest of Your Life</a> — Monte Carlo, PDF e importância amostral — / <a href="https://raytracing.github.io/books/RayTracingTheRestOfYourLife.html" target="_blank" rel="noreferrer">Livro</a></li><li><a href="https://pbr-book.org/" target="_blank" rel="noreferrer">PBRT - Physically Based Rendering (3ª e 4ª ed)</a> — / <a href="https://pbr-book.org/" target="_blank" rel="noreferrer">Livro Completo Grátis</a> / <a href="https://github.com/mmp/pbrt-v4" target="_blank" rel="noreferrer">Código Fonte GitHub</a> / <a href="https://pbr-book.org/4ed/index" target="_blank" rel="noreferrer">Documentação</a></li><li><a href="https://www.scratchapixel.com/" target="_blank" rel="noreferrer">Scratchapixel 3.0</a> — / <a href="https://www.scratchapixel.com/index.html" target="_blank" rel="noreferrer">Visão Geral</a> / <a href="https://www.scratchapixel.com/lessons/3d-basic-rendering/introduction-acceleration-structures" target="_blank" rel="noreferrer">Aceleração BVH</a> / <a href="https://www.scratchapixel.com/lessons/3d-basic-rendering/minimal-ray-tracer-rendering-simple-shapes" target="_blank" rel="noreferrer">Matemática de Raios</a></li><li><a href="https://www.kevinbeason.com/smallpt/" target="_blank" rel="noreferrer">SmallPT: 99 linhas de C++ Path Tracer</a> — / <a href="https://www.kevinbeason.com/smallpt/" target="_blank" rel="noreferrer">Website</a> / <a href="https://www.kevinbeason.com/smallpt/" target="_blank" rel="noreferrer">Código C++</a> / <a href="https://docs.google.com/presentation/d/1_A-49K6aT2ghOzke_J6m_F1eT_A9k_vW/present" target="_blank" rel="noreferrer">Explicativo</a></li><li><a href="https://gabrielgambetta.com/computer-graphics-from-scratch/" target="_blank" rel="noreferrer">Computer Graphics from Scratch</a> — / <a href="https://gabrielgambetta.com/computer-graphics-from-scratch/02-basic-raytracing.html" target="_blank" rel="noreferrer">Capítulo Raytracer</a> / <a href="https://gabrielgambetta.com/computer-graphics-from-scratch/demos/raytracer-01.html" target="_blank" rel="noreferrer">Demonstração Web</a></li></ul><h3 id="⚙️-motores-de-producao-e-pesquisa" tabindex="-1">⚙️ Motores de Produção e Pesquisa <a class="header-anchor" href="#⚙️-motores-de-producao-e-pesquisa" aria-label="Permalink to “⚙️ Motores de Produção e Pesquisa”">​</a></h3><ul><li><a href="https://www.mitsuba-renderer.org/" target="_blank" rel="noreferrer">Mitsuba 3</a> — renderizador pesquisável e diferenciável — / <a href="https://www.mitsuba-renderer.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/mitsuba-renderer/mitsuba3" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://mitsuba.readthedocs.io/" target="_blank" rel="noreferrer">Docs</a></li><li><a href="https://luxcorerender.org/" target="_blank" rel="noreferrer">LuxCoreRender</a> — motor open source de iluminação global e path tracing — / <a href="https://luxcorerender.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/LuxCoreRender/LuxCore" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://forums.luxcorerender.org/" target="_blank" rel="noreferrer">Fórum</a></li><li><a href="https://www.cycles-renderer.org/" target="_blank" rel="noreferrer">Cycles (Blender)</a> — motor de produção baseado em física do Blender — / <a href="https://docs.blender.org/manual/en/latest/render/cycles/" target="_blank" rel="noreferrer">Docs</a> / <a href="https://github.com/blender/blender/tree/main/intern/cycles" target="_blank" rel="noreferrer">Código Fonte</a></li><li><a href="https://openmoonray.org/" target="_blank" rel="noreferrer">MoonRay (DreamWorks)</a> — renderizador de animações de Hollywood open source — / <a href="https://openmoonray.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/dreamworksanimation/openmoonray" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://openmoonray.org/documentation" target="_blank" rel="noreferrer">Docs</a></li><li><a href="https://appleseedhq.net/" target="_blank" rel="noreferrer">Appleseed</a> — renderizador baseado em física para animação e VFX — / <a href="https://appleseedhq.net/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/appleseedhq/appleseed" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/tunabrain/tungsten" target="_blank" rel="noreferrer">Tungsten</a> — renderizador de alta performance em C++11 — / <a href="https://github.com/tunabrain/tungsten" target="_blank" rel="noreferrer">GitHub</a></li></ul><h3 id="⚡-apis-e-aceleracao-de-hardware-em-tempo-real" tabindex="-1">⚡ APIs e Aceleração de Hardware em Tempo Real <a class="header-anchor" href="#⚡-apis-e-aceleracao-de-hardware-em-tempo-real" aria-label="Permalink to “⚡ APIs e Aceleração de Hardware em Tempo Real”">​</a></h3><ul><li><a href="https://developer.nvidia.com/rtx/ray-tracing" target="_blank" rel="noreferrer">NVIDIA RTX &amp; DXR Tutorials</a> — / <a href="https://developer.nvidia.com/rtx/ray-tracing" target="_blank" rel="noreferrer">Guia Oficial</a> / <a href="https://developer.nvidia.com/rtx/raytracing/dxr/DX12-Raytracing-tutorial-Part-1" target="_blank" rel="noreferrer">Tutorial DXR</a> / <a href="https://github.com/NVIDIA-RTX/RayTracingBaseWalkthrough" target="_blank" rel="noreferrer">GitHub Samples</a></li><li><a href="https://nvpro-samples.github.io/vk_raytracing_tutorial_KHR/" target="_blank" rel="noreferrer">Vulkan Ray Tracing Tutorial</a> — / <a href="https://nvpro-samples.github.io/vk_raytracing_tutorial_KHR/" target="_blank" rel="noreferrer">Tutorial Oficial</a> / <a href="https://github.com/nvpro-samples/vk_raytracing_tutorial_KHR" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.embree.org/" target="_blank" rel="noreferrer">Intel Embree</a> — kernels otimizados para SSE, AVX, AVX-512 e ARM NEON — / <a href="https://www.embree.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/embree/embree" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://www.embree.org/documentation.html" target="_blank" rel="noreferrer">Documentação</a></li><li><a href="https://www.openimagedenoise.org/" target="_blank" rel="noreferrer">Intel Open Image Denoise (OIDN)</a> — biblioteca de IA para desruído de traçado de raios — / <a href="https://www.openimagedenoise.org/" target="_blank" rel="noreferrer">Website</a> / <a href="https://github.com/OpenImageDenoise/oidn" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://developer.nvidia.com/optix" target="_blank" rel="noreferrer">NVIDIA OptiX SDK</a> — framework para construção de ray tracers em GPU — / <a href="https://developer.nvidia.com/optix" target="_blank" rel="noreferrer">Website</a> / <a href="https://raytracing-docs.nvidia.com/optix8/guide/index.html" target="_blank" rel="noreferrer">Guia de Programação</a></li></ul><h3 id="🔬-papers-e-recursos-avancados" tabindex="-1">🔬 Papers e Recursos Avançados <a class="header-anchor" href="#🔬-papers-e-recursos-avancados" aria-label="Permalink to “🔬 Papers e Recursos Avançados”">​</a></h3><ul><li><a href="https://developer.nvidia.com/ray-tracing-gems" target="_blank" rel="noreferrer">NVIDIA Ray Tracing Gems I &amp; II (PDFs Gratuitos)</a> — / <a href="https://www.realtimerendering.com/raytracinggems/rtg/index.html" target="_blank" rel="noreferrer">RT Gems 1</a> / <a href="https://www.realtimerendering.com/raytracinggems/rtg2/index.html" target="_blank" rel="noreferrer">RT Gems 2</a> / <a href="https://github.com/Apress/ray-tracing-gems" target="_blank" rel="noreferrer">Código Fonte GitHub</a></li><li><a href="https://www.cs.cmu.edu/afs/cs/academic/class/15462-s15/www/lec_slides/kajiya86.pdf" target="_blank" rel="noreferrer">Kajiya 1986 - The Rendering Equation</a> — o paper seminal de iluminação global</li><li><a href="https://dl.acm.org/doi/10.1145/358876.358882" target="_blank" rel="noreferrer">Whitted 1980 - An Improved Illumination Model for Shaded Display</a> — introdução ao ray tracing recursivo</li></ul>`,22)]))}});export{a as __pageData,o as default};